import Foundation
import Testing

// Fixtures are generated by Tools/extractor (npm test), which runs the real
// Preprocess.js over saved pages. To add a site: export its entry from the
// app's Diagnostics screen, save the snapshot JSON here, and add a test.

private final class FixtureToken {}

private func fixture(_ name: String) throws -> PageSnapshot {
    let url = try #require(Bundle(for: FixtureToken.self).url(forResource: name + ".snapshot", withExtension: "json"))
    return try #require(PageSnapshot.decode(try String(contentsOf: url, encoding: .utf8)))
}

private func spec(_ d: ListingDraft, _ label: String) -> String? {
    d.specs.first { $0.label == label }?.value
}

@Suite("Listing interpreter")
struct ListingInterpreterTests {
    @Test func eBayUK() throws {
        let d = ListingInterpreter.interpret(try fixture("ebay-uk"))
        #expect(d.brand == "Rolex")
        #expect(d.model == "Submariner Date")
        #expect(d.reference == "126610LN")
        #expect(d.price == Money(amount: 12950, currency: "GBP"))
        #expect(d.sourceURL?.absoluteString == "https://www.ebay.co.uk/itm/325512345678")
        #expect(d.siteName == "eBay")
        #expect(d.imageURLs.map(\.absoluteString) == [
            "https://i.ebayimg.com/images/g/AbCdEfGhIj/s-l1600.jpg",
            "https://i.ebayimg.com/images/g/KlMnOpQrSt/s-l1600.jpg",
        ])
        #expect(spec(d, "Case size") == "41 mm")
        #expect(spec(d, "Condition") == "Pre-owned")
        #expect(spec(d, "Year") == "2021")
    }

    @Test func eBayUSWithoutStructuredData() throws {
        let d = ListingInterpreter.interpret(try fixture("ebay-us-no-jsonld"))
        #expect(d.brand == "Omega")
        #expect(d.model == "Speedmaster Professional Moonwatch")
        #expect(d.reference == "311.30.42.30.01.005")
        #expect(d.price == Money(amount: 4250, currency: "USD"))
        #expect(spec(d, "Calibre") == "1861")
        #expect(spec(d, "Case size") == "42 mm")
        #expect(d.imageURLs.first?.absoluteString == "https://i.ebayimg.com/images/g/ZZZZzzzz/s-l1600.jpg")
    }

    @Test func shopify() throws {
        let d = ListingInterpreter.interpret(try fixture("shopify"))
        // JSON-LD names the shop as brand; the Shopify vendor is the real one.
        #expect(d.brand == "Tudor")
        #expect(d.model == "Black Bay 58")
        #expect(d.reference == "M79030N-0001")
        #expect(d.price == Money(amount: 3150, currency: "GBP"))
        #expect(d.siteName == "Northern Time Co.")
        #expect(d.imageURLs.map(\.absoluteString) == [
            "https://northerntime.example/cdn/shop/files/bb58-front.jpg?v=1700000000&width=1600",
            "https://northerntime.example/cdn/shop/files/bb58-side.jpg?v=1700000001&width=1600",
        ])
        #expect(spec(d, "Power reserve") == "70 hours")
    }

    @Test func brandSite() throws {
        let d = ListingInterpreter.interpret(try fixture("brand-site"))
        #expect(d.brand == "Omega")
        #expect(d.model == "Seamaster Diver 300M")
        #expect(d.reference == "210.30.42.20.03.001")
        #expect(d.price == Money(amount: 5900, currency: "GBP"))
        #expect(spec(d, "Case size") == "42 mm")
        #expect(spec(d, "Calibre") == "OMEGA 8800")
        #expect(d.imageURLs.count == 1)
    }

    @Test func aggregateOfferAndImageObject() throws {
        let json = """
        {"url":"https://shop.example/p/1","jsonld":[{"@type":"Product","name":"Grand Seiko SBGA211 Snowflake",
         "offers":{"@type":"AggregateOffer","lowPrice":"5,100","priceCurrency":"GBP"},
         "image":{"@type":"ImageObject","url":"https://shop.example/a.jpg"}}]}
        """
        let d = ListingInterpreter.interpret(try #require(PageSnapshot.decode(json)))
        #expect(d.brand == "Grand Seiko")
        #expect(d.reference == "SBGA211")
        #expect(d.model == "Snowflake")
        #expect(d.price == Money(amount: 5100, currency: "GBP"))
        #expect(d.imageURLs.map(\.absoluteString) == ["https://shop.example/a.jpg"])
    }

    @Test func titleOnlyFallback() {
        var d = ListingDraft()
        d.siteName = "eBay"
        ListingInterpreter.applyTitle("Men's Rolex GMT-Master II 126710BLRO Pepsi | eBay", to: &d)
        #expect(d.brand == "Rolex")
        #expect(d.reference == "126710BLRO")
        #expect(d.model == "GMT-Master II Pepsi")
    }

    @Test(arguments: [
        ("Tudor Black Bay 58 M79030N-0001", "Tudor", "M79030N-0001", "Black Bay 58"),
        ("Omega Seamaster Aqua Terra 150M 41mm Blue Dial", "Omega", "", "Seamaster Aqua Terra 150M"),
        ("Rolex Oyster Perpetual 41 124300 Green Dial Box Papers", "Rolex", "124300", "Oyster Perpetual 41"),
        ("Cartier Santos de Cartier Large WSSA0018", "Cartier", "WSSA0018", "Santos de Cartier Large"),
    ])
    func deriveModel(title: String, brand: String, reference: String, expected: String) {
        #expect(ListingInterpreter.deriveModel(from: title, brand: brand, reference: reference) == expected)
    }

    @Test func cleanTitle() {
        #expect(ListingInterpreter.cleanTitle("Seamaster Diver 300M | OMEGA UK®", siteName: "OMEGA") == "Seamaster Diver 300M")
        #expect(ListingInterpreter.cleanTitle("Tudor Black Bay 58 – Northern Time Co.", siteName: "Northern Time Co.") == "Tudor Black Bay 58")
    }
}

@Suite("Price parser")
struct PriceParserTests {
    @Test(arguments: [
        ("£12,950.00", nil, "12950", "GBP"),
        ("US $4,250.00", nil, "4250", "USD"),
        ("€ 2.300,00", nil, "2300", "EUR"),
        ("CHF 8'900.–", nil, "8900", "CHF"),
        ("3150.0", "GBP", "3150", "GBP"),
        ("1.650", "EUR", "1650", "EUR"),
        ("£3,150.00 GBP", nil, "3150", "GBP"),
        ("12 950 €", nil, "12950", "EUR"),
        ("From £1,000 - £2,000", nil, "1000", "GBP"),
        ("£949.99", nil, "949.99", "GBP"),
    ] as [(String, String?, String, String)])
    func parses(text: String, fallback: String?, amount: String, currency: String) {
        #expect(PriceParser.parse(text, fallbackCurrency: fallback) == Money(amount: Decimal(string: amount)!, currency: currency))
    }

    @Test func needsACurrency() {
        #expect(PriceParser.parse("3150") == nil)
    }

    @Test func pence() {
        #expect(Money(amount: Decimal(string: "949.99")!, currency: "GBP").pence == 94999)
        #expect(PriceFormatter.pence(fromEditing: "12,950") == 1_295_000)
        #expect(PriceFormatter.editingText(pence: 94999) == "949.99")
    }
}

@Suite("Reference detector")
struct ReferenceDetectorTests {
    @Test(arguments: [
        ("Rolex Submariner Date 126610LN 41mm Black Dial 2021", "126610LN"),
        ("Grand Seiko SBGA211 Snowflake", "SBGA211"),
        ("Patek Philippe Nautilus 5711/1A-010", "5711/1A-010"),
        ("Rolex Explorer Ref. 1016 from 1968", "1016"),
        ("IWC Pilot's Mark XVIII IW327001", "IW327001"),
    ])
    func finds(text: String, expected: String) {
        #expect(ReferenceDetector.best(in: text) == expected)
    }

    @Test(arguments: ["Omega Seamaster Diver 300M", "Rolex 2023 Datejust 41 mm", "Seiko 5 Sports £249"])
    func ignores(text: String) {
        #expect(ReferenceDetector.best(in: text) == nil)
    }
}
